      "ur": "زمین پر چلنے پھرنے والے جتنے جاندار ہیں سب کی روزیاں اللہ تعالیٰ پر ہیں[1] وہی ان کے رہنے سہنے کی جگہ کو جانتا ہےاور ان کے سونپے جانے[2] کی جگہ کو بھی، سب کچھ واضح کتاب میں موجود ہے.",
      "en": "And there is no creature on earth but that upon Allāh is its provision, and He knows its place of dwelling and place of storage.[548] All is in a clear register.",
      "footnotesUr": "[1] یعنی وہ کفیل اور ذمے دار ہے۔ زمین پر چلنے والی ہر مخلوق، انسان ہو یا جن، چرند ہو یا پرند، چھوٹی ہو یا بڑی، بحری ہو یا بری۔ ہر ایک کو اس کی ضروریات کے مطابق وہ خوراک مہیا کرتا ہے۔\n[2] مستقر اور مستودع کی تعریف میں اختلاف ہے بعض کے نزدیک منتہائے سیر (یعنی زمین میں چل پھر کر جہاں رک جائے) مستقر ہے اور جس کو ٹھکانا بنائے وہ مستودع ہے۔ بعض کے نزدیک رحم مادر مستقر اور باپ کی صلب مستودع ہے اور بعض کے نزدیک زندگی میں انسان یا حیوان جہاں رہائش پذیر ہو وہ اس کا مستقر ہے اور جہاں مرنے کے بعد دفن ہو وہ مستودع ہے (تفسیر ابن کثیر) امام شوکانی کہتے ہیں مستقر سے مراد رحم مادر اور مستودع سے وہ حصہ زمین ہے جس میں دفن ہو اور امام حاکم کی ایک روایت کی بنیاد پر اسی کو ترجیح دی ہے بہرحال جو بھی مطلب لیا جائے آیت کا مفہوم واضح ہے کہ چونکہ اللہ تعالٰی کو ہر ایک کے مستقر ومستودع کا علم ہے اس لیے وہ ہر ایک کو روزی پہنچانے پر قادر ہے اور ذمے دار ہے اور وہ اپنی ذمے داری پوری کرتا ہے۔",
      "footnotesEn": "[548] Before birth and after death.",
