      "number": 11,
      "arFull": "اِلَّا الَّذِیْنَ صَبَرُوْا وَعَمِلُوا الصّٰلِحٰتِ ؕ اُولٰٓىِٕكَ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ كَبِیْرٌ ۟",
      "ur": "سوائے ان کے جو صبر کرتے ہیں اور نیک کاموں میں لگے رہتے ہیں۔ انہی لوگوں کے لئے بخشش بھی ہے اور بہت بڑا نیک[1] بدلہ بھی.",
      "en": "Except for those who are patient and do righteous deeds; those will have forgiveness and great reward.",
      "footnotesUr": "[1] یعنی اہل ایمان، راحت و فراغت ہو یا تنگی اور مصیبت، دونوں حالتوں میں اللہ کے احکام کے مطابق طرز عمل اختیار کرتے ہیں جیسا کہ حدیث میں آتا ہے نبی (صلى الله عليه وسلم) نے قسم کھا کر فرمایا ”قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، اللہ تعالٰی مومن کے لئے جو بھی فیصلہ فرماتا ہے، اس میں اس کے لئے بہتری کا پہلو ہوتا ہے۔ اگر اس کو کئی راحت پہنچتی ہے تو اس پر اللہ کا شکر کرتا ہے اور اگر کوئی تکلیف پہنچتی ہے تو صبر کرتا ہے، یہ بھی اس کے لئے بہتر (یعنی اجر و ثواب کا باعث) ہے۔ یہ امتیاز ایک مومن کے سوا کسی کو حاصل نہیں“۔ (صحيح مسلم، كتاب الزهد، باب المؤمن أمره كله خير) اور ایک اور حدیث میں فرمایا کہ ”مومن کو جو بھی فکر و غم اور تکلیف پہنچتی ہے حتی کہ اسے کانٹا چبھتا ہے تو اللہ تعالٰی اس کی وجہ سے اس کی غلطیاں معاف فرما دیتا ہے“۔(ﻣﺴﻨﺪ ﺍﺣﻤﺪ ﺟﻠﺪ ٣ ،ﺹ٤) سورہ معاج کی آیات ۱۹-۲۲ میں بھی یہ مضمون بیان کیا گیا ہے۔",
