      "arFull": "وَلَقَدْ اَرْسَلْنَا نُوْحًا اِلٰی قَوْمِهٖۤ ؗ اِنِّیْ لَكُمْ نَذِیْرٌ مُّبِیْنٌ ۟ۙ",
