      "number": 26,
      "arFull": "اَنْ لَّا تَعْبُدُوْۤا اِلَّا اللّٰهَ ؕ اِنِّیْۤ اَخَافُ عَلَیْكُمْ عَذَابَ یَوْمٍ اَلِیْمٍ ۟",
      "ur": "کہ تم صرف اللہ ہی کی عبادت کرو[1] ، مجھے تو تم پر دردناک دن کے عذاب کا خوف ہے[2]۔",
      "en": "That you not worship except Allāh. Indeed, I fear for you the punishment of a painful day.\"",
      "footnotesUr": "[1] یہ وہی دعوت توحید ہے جو ہر نبی نے آ کر اپنی اپنی قوم کو دی۔ جس طرح فرمایا «وَمَآ اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَّسُوْلٍ اِلَّا نُوْحِيْٓ اِلَيْهِ اَنَّهٗ لَآ اِلٰهَ اِلَّآ اَنَا فَاعْبُدُوْنِ» (الانبیاء: 25) ”جو پیغمبر ہم نے آپ سے پہلے بھیجے، ان کی طرف یہی وحی کی کہ میرے سوا کوئی معبود نہیں، پس میری ہی عبادت کرو“۔\n[2] یعنی اگر مجھ پر ایمان نہیں لائے اور اس دعوت توحید کو نہیں اپنایا تو عذاب الٰہی سے نہیں بچ سکو گے۔",
      "footnotesEn": null,
