      "arFull": "وَنَادٰی نُوْحٌ رَّبَّهٗ فَقَالَ رَبِّ اِنَّ ابْنِیْ مِنْ اَهْلِیْ وَاِنَّ وَعْدَكَ الْحَقُّ وَاَنْتَ اَحْكَمُ الْحٰكِمِیْنَ ۟",
