      "footnotesUr": "[1] عاد کی طرف صرف ایک نبی حضرت ہود (عليه السلام) ہی بھیجے گئے تھے، یہاں اللہ تعالٰی نے فرمایا کہ انہوں نے اللہ کے رسولوں کی نافرمانی کی۔ اس سے یا تو یہ واضح کرنا مقصود ہے کہ ایک رسول کی تکذیب، یہ گویا تمام رسولوں کی تکذیب ہے۔ کیونکہ تمام رسولوں پر ایمان رکھنا ضروری ہے۔ یا مطلب یہ ہے کہ یہ قوم اپنے کفر اور انکار میں اتنی آگے بڑھ چکی تھی کہ حضرت ہود (عليه السلام) کے بعد اگر ہم اس قوم میں متعدد رسول بھی بھیجتے، تو یہ قوم ان سب کی تکذیب ہی کرتی۔ اور اس سے قطعاً یہ امید نہ تھی کہ وہ کسی بھی رسول پر ایمان لے آتی۔ یا ہو سکتا ہے کہ اور بھی انبیاء بھیجے گئے ہوں اور اس قوم نے ہر ایک کی تکذیب کی۔\n[2] یعنی اللہ کے پیغمبروں کی تکذیب کی لیکن جو لوگ اللہ کے حکموں سے سرکشی کرنے والے اور نافرمان تھے، ان کی اس قوم نے پیروی کی۔",
