      "footnotesUr": "[1] اس آیت میں هِيَ کا مرجع بعض مفسرین کے نزدیک وہ نشان زدہ کنکریلے پتھر ہیں جو ان پر برسائے گئے اور بعض کے نزدیک اس کا مرجع وہ بستیاں ہیں جو ہلاک کی گئیں اور جو شام اور مدینہ کے درمیان تھیں اور ظالمین سے مراد مشرکین مکہ اور دیگر مکذبین ہیں۔ مقصد ان کو ڈرانا ہے کہ تمہارا حشر بھی ویسا ہہی ہو سکتا ہے جس سے گزشتہ قومیں دو چار ہوئیں۔",
