      "arFull": "وَكُلًّا نَّقُصُّ عَلَیْكَ مِنْ اَنْۢبَآءِ الرُّسُلِ مَا نُثَبِّتُ بِهٖ فُؤَادَكَ ۚ وَجَآءَكَ فِیْ هٰذِهِ الْحَقُّ وَمَوْعِظَةٌ وَّذِكْرٰی لِلْمُؤْمِنِیْنَ ۟",
