      "arFull": "وَلِلّٰهِ غَیْبُ السَّمٰوٰتِ وَالْاَرْضِ وَاِلَیْهِ یُرْجَعُ الْاَمْرُ كُلُّهٗ فَاعْبُدْهُ وَتَوَكَّلْ عَلَیْهِ ؕ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُوْنَ ۟۠",
      "ur": "زمینوں اور آسمانوں کا علم غیب اللہ تعالیٰ ہی کو ہے، تمام معاملات کا رجوع بھی اسی کی جانب ہے، پس تجھے اسی کی عبادت کرنی چاہئے اور اسی پر بھروسہ رکھنا چاہئے اور تم جو کچھ کرتے ہو اس سے اللہ تعالیٰ بے خبر نہیں.",
      "en": "And to Allāh belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do.",
